; top.asm -- chapter 12: the stack at the top of memory
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "top.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; The stack where a program for another machine might put it, at the top of
; memory, and 320 calls deep, with the interrupt on. The BIOS's work
; area and its hooks are up there (chapter 3).
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        VDP_REG 1, $A0          ; the display off, its interrupt on
        im 1
        ld sp, 0                ; the stack at the top of memory
        ld de, 320
        call dig                ; 320 calls deep, and waits there
back:   jr back                 ; never reached
stop:   jr stop

; dig: calls itself until DE runs out, then waits for interrupts at the
;      bottom, 320 ways back on the stack above it
dig:    dec de
        ld a, d
        or e
        jr z, deep
        call dig
        ret
deep:   ei                      ; interrupts on, the stack 640 bytes deep
wait:   halt
        jr wait
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
